{
  "category_edits": [
    {
      "category": "sequence_modeling",
      "rationale": "Reduce maximum causal context to max(1, floor(0.75 * L)) for all four datasets to reduce stale-history interference and recurrent computation. Existing sampling preserves the most recent interactions in chronological order; saved maxlen metadata applies the identical truncation in the generated predictor. Preserve the GRU architecture, readout, loss, optimizer, splits and epoch settings.",
      "edits": [
        {
          "find": "MAXLEN        = int(os.environ.get(\"GRU4REC_MAXLEN\", \"128\"))",
          "replace": "MAXLEN        = max(1, (3 * int(os.environ.get(\"GRU4REC_MAXLEN\", \"128\"))) // 4)"
        }
      ]
    }
  ],
  "change_summary": "Reduce causal context from 128 to 96 by default, consistently across training, validation and metadata-driven prediction for all four categories."
}
